class Trie:
    def __init__(self):
        self.children = {}
        self.is_word = False

def find_words(board, words):
    trie = Trie()
    for w in words:
        node = trie
        for c in w:
            node = node.children.setdefault(c, Trie())
        node.is_word = True
    m, n = len(board), len(board[0])
    out = set()
    def dfs(i, j, node, path):
        c = board[i][j]
        if c not in node.children:
            return
        nxt = node.children[c]
        if nxt.is_word:
            out.add(path + c)
        board[i][j] = '#'
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < m and 0 <= nj < n and board[ni][nj] != '#':
                dfs(ni, nj, nxt, path + c)
        board[i][j] = c
    for i in range(m):
        for j in range(n):
            dfs(i, j, trie, '')
    return list(out)
